use crate::aap::caps::notifier;

/// Upper bound on the notification body, in characters. Feed-supplied text is
/// adversarial and unbounded in size, so the body is capped before it crosses
/// the boundary.
const MAX_MESSAGE_CHARS: usize = 4000;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept_count = composed.entries.iter().filter(|e| e.kept).count();

        let mut message = format!("Digest {}: {} item(s)", composed.date, kept_count);
        for entry in composed.entries.iter().filter(|e| e.kept) {
            message.push('\n');
            message.push_str("- ");
            message.push_str(&entry.title);
            message.push_str(" <");
            message.push_str(&entry.link);
            message.push('>');
        }
        let message = cap(message, MAX_MESSAGE_CHARS);

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

/// Truncate `text` to at most `max` characters, marking the cut with an ellipsis.
fn cap(text: String, max: usize) -> String {
    if text.chars().count() <= max {
        return text;
    }
    let mut out: String = text.chars().take(max).collect();
    out.push('…');
    out
}

export!(Node);
